<?php
require_once '../../middleware/jsonMiddleware.php';require_once '../../middleware/requestLogger.php';require_once '../../middleware/corsMiddleware.php';require_once '../../middleware/authMiddleware.php';require_once '../../utils/response.php';require_once '../../config/database.php';use MongoDB\BSON\ObjectId;use MongoDB\BSON\UTCDateTime;
setJsonResponse();handleCors();logRequest();requireAdmin();if($_SERVER['REQUEST_METHOD']!=='PUT')sendResponse(false,'Method not allowed.',null,405);$d=json_decode(file_get_contents('php://input'),true);$id=trim($d['id']??'');$decision=$d['decision']??'';if(!preg_match('/^[a-f0-9]{24}$/i',$id)||!in_array($decision,['Approved','Rejected'],true))sendResponse(false,'Invalid booking decision.',null,400);
try{$db=getDatabase();$b=$db->bookings->findOne(['_id'=>new ObjectId($id),'status'=>'Pending']);if(!$b)sendResponse(false,'Pending booking not found.',null,404);if($decision==='Approved'){$conflict=$db->bookings->findOne(['_id'=>['$ne'=>$b['_id']],'vehicleId'=>$b['vehicleId'],'status'=>['$in'=>['Approved','Confirmed','Active','Returned']],'startDate'=>['$lte'=>$b['endDate']],'endDate'=>['$gte'=>$b['startDate']]]);if($conflict)sendResponse(false,'Cannot approve this request because the vehicle is already reserved for overlapping dates.',null,409);}$db->bookings->updateOne(['_id'=>$b['_id']],['$set'=>['status'=>$decision,'paymentStatus'=>$decision==='Approved'?'Awaiting Payment':'Not Paid','updatedAt'=>new UTCDateTime()]]);sendResponse(true,$decision==='Approved'?'Booking approved. It is now awaiting customer payment.':'Booking request rejected.');}catch(Throwable $e){sendResponse(false,'Unable to update booking.',null,500);}
